// === Tab: MyCircle ===
class MyCircle{
	constructor(x,y,r){
		this.x = x
		this.y = y
		this.a = random(TAU)
		this.dir = true
		this.r = r
		this.rotation = TAU/8 * int(random(8))
	}
	display(dt){
		push()
		translate(this.x,this.y)
		rotate(this.rotation)
		noFill()
		strokeWeight(this.r*2)
		stroke(0)
		arc(0,0,this.r*2,this.r*2,this.a,TAU)
		line(this.r,0,this.r,this.a*this.r)
		stroke(255)
		strokeWeight(this.r*1.2)
		point(this.r,this.a*this.r)
		stroke(0)
		strokeWeight(this.r*0.5)
		point(this.r,this.a*this.r)
		pop()
		if(this.dir){
			this.a+=0.05/this.r*dt
		}else{
			this.a-=0.05/this.r*dt
		}
		if(this.a>TAU){
			this.dir = false
			this.a = TAU
		}else if(this.a<0){
			this.a = 0
			this.dir = true
		}
	}
}

