let array = []
function setup() {
	createCanvas(800,800);
	background(255);
	for(let j = -2; j <= 2; j++){
		for(let i = -2; i <= 2; i++){
			array.push(new MyCircle(width/2 + i*100,height/2 + j*100,10))
		}
	}
}

function draw() {
	background(255);
	array.forEach(x => x.display(deltaTime))
}

function mousePressed(){
	save('eels.png')
}
